class Resource extends Vector {
 heading='A district of small possibilities.';note='Choose a building. Every face has its own light.';
 build(){const random=seedRandom(this.number('seed',12,1,100)),count=this.number('detail',6,3,8),size=170/count;this.buildings=[];let shapes='';const project=(x,y,z)=>({x:360+(x-y)*size,y:130+(x+y)*size*.52-z});for(let y=0;y<count;y++)for(let x=0;x<count;x++){const index=y*count+x,height=20+random()*90,px=x-count/2,py=y-count/2;const a=project(px,py,height),b=project(px+0.75,py,height),c=project(px+0.75,py+0.75,height),d=project(px,py+.75,height),af=project(px,py,0),bf=project(px+.75,py,0),cf=project(px+.75,py+.75,0);this.buildings.push({index,height:Math.round(height)});const points=p=>p.map(v=>`${v.x.toFixed(2)},${v.y.toFixed(2)}`).join(' ');shapes+=`<g data-handle="${index}" tabindex="0" role="button" aria-label="Building ${index+1}, ${Math.round(height)} units tall"><polygon points="${points([a,b,bf,af])}" fill="#688e7a" stroke="#1d3b2c" stroke-width=".6"/><polygon points="${points([b,c,cf,bf])}" fill="#365b49" stroke="#1d3b2c" stroke-width=".6"/><polygon points="${points([a,b,c,d])}" fill="${index===this.selected?this.color:'#b0c6a5'}" stroke="#dae4c488" stroke-width=".5"/>${Array.from({length:Math.floor(height/15)},(_,i)=>{const p=project(px+.8,py+.15,10+i*13);return`<path d="M${p.x} ${p.y}l${-size*.23} ${size*.12}" stroke="#c6d7b3" stroke-width="1.2"/>`;}).join('')}</g>`;}
 return this.svg(`<defs><linearGradient id="${this.artId}-ground" x2="1" y2="1"><stop stop-color="#aab39c"/><stop offset="1" stop-color="#506f5f"/></linearGradient></defs><polygon points="360,45 640,210 360,380 80,210" fill="url(#${this.artId}-ground)" stroke="#d6dac04d"/>${shapes}<text x="360" y="400" text-anchor="middle" fill="${this.color}" font-family="monospace" font-size="9" letter-spacing="2">${this.selected===undefined?'A NEW DISTRICT / SELECT A BUILDING':`BUILDING ${this.selected+1} / HEIGHT ${this.buildings[this.selected]?.height||0}`}</text>`);}
 interact(index){this.selected=index;this.draw();this.emit('building-select',this.buildings[index]);}
 keyHandle(index,key){if(key==='Enter'||key===' ')this.interact(index);}
}
